<?php

namespace App\Models;

use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Database\Eloquent\Relations\HasMany;

/**
 * @property string $name If generated by the CLI this will be "cli", otherwise user-provided
 * @property mixed $encryptedToken This is the token encrypted using the ENCRYPTION_KEY
 * @property string $obfuscatedToken This is shown in the UI, with ********
 * @property string $hashedToken This is used to find the token in the database
 * @property \Carbon\CarbonInterface|null $expiresAt After this the token no longer authenticates. Null means it never expires.
 * @property int|null $idleTimeoutSeconds Set on CLI login tokens: they stop authenticating this many seconds after their last use
 * (or creation, if never used). Null means no idle limit.
 * @property \Carbon\CarbonInterface|null $expiryReminderSentAt When the "about to expire" email was sent. Set before sending, so it's sent at most once.
 * @property \Carbon\CarbonInterface|null $expiredNoticeSentAt When the "has expired" email was sent. Set before sending, so it's sent at most once.
 */
class PersonalAccessToken extends Model
{
    use PrismaDates;

    const CREATED_AT = 'createdAt';
    const UPDATED_AT = 'updatedAt';

    protected $table = 'PersonalAccessToken';

    protected $keyType = 'string';

    public $incrementing = false;

    protected $fillable = [
        'id',
        'name',
        'encryptedToken',
        'obfuscatedToken',
        'hashedToken',
        'userId',
        'revokedAt',
        'lastAccessedAt',
        'expiresAt',
        'idleTimeoutSeconds',
        'expiryReminderSentAt',
        'expiredNoticeSentAt',
        'oauthClientId',
    ];

    protected $casts = [
        'encryptedToken' => 'array',
        'revokedAt' => 'datetime',
        'lastAccessedAt' => 'datetime',
        'expiresAt' => 'datetime',
        'idleTimeoutSeconds' => 'integer',
        'expiryReminderSentAt' => 'datetime',
        'expiredNoticeSentAt' => 'datetime',
    ];

    public function user(): BelongsTo
    {
        return $this->belongsTo(User::class, 'userId');
    }

    public function oauthClient(): BelongsTo
    {
        return $this->belongsTo(OAuthClient::class, 'oauthClientId');
    }

    public function authorizationCodes(): HasMany
    {
        return $this->hasMany(AuthorizationCode::class, 'personalAccessTokenId');
    }

    public function oauthRefreshTokens(): HasMany
    {
        return $this->hasMany(OAuthRefreshToken::class, 'personalAccessTokenId');
    }
}